window.loadWfAnalytics = async function() {
    const spinner = document.getElementById('wf-analytics-spinner');
    const content = document.getElementById('wf-analytics-content');
    if (!content) return;
    
    try {
        const data = await apiCall('crm/automation.php?action=get_logs');
        const logs = data.logs || [];
        
        // Calculate metrics
        const total = logs.length;
        const successes = logs.filter(l => l.status === 'success').length;
        const failures = total - successes;
        const successRate = total > 0 ? Math.round((successes / total) * 100) : 100;
        
        const sumDuration = logs.reduce((sum, l) => sum + parseFloat(l.execution_time || 0), 0);
        const avgDuration = total > 0 ? (sumDuration / total).toFixed(2) : 0;
        
        // Populate stats
        document.getElementById('stat-total-runs').textContent = total;
        document.getElementById('stat-success-rate').textContent = `${successRate}%`;
        document.getElementById('stat-avg-time').textContent = `${avgDuration * 1000} ms`;
        document.getElementById('stat-failed-runs').textContent = failures;
        
        if (spinner) spinner.classList.add('hidden');
        content.classList.remove('hidden');
        
        // Build Executions Over Time chart using Chart.js
        const canvas = document.getElementById('wf-analytics-chart');
        if (!canvas) return;
        
        // Group logs by date
        const dateGroups = {};
        logs.slice().reverse().forEach(l => {
            const date = new Date(l.created_at).toLocaleDateString();
            dateGroups[date] = (dateGroups[date] || 0) + 1;
        });
        
        const labels = Object.keys(dateGroups);
        const chartData = Object.values(dateGroups);
        
        // Destroy existing chart if any
        if (window.wfState.analyticsChart) {
            window.wfState.analyticsChart.destroy();
        }
        
        window.wfState.analyticsChart = new Chart(canvas, {
            type: 'line',
            data: {
                labels: labels.length > 0 ? labels : ['No Runs'],
                datasets: [{
                    label: 'Workflow Runs',
                    data: chartData.length > 0 ? chartData : [0],
                    borderColor: 'rgb(79, 70, 229)',
                    backgroundColor: 'rgba(79, 70, 229, 0.1)',
                    tension: 0.3,
                    fill: true,
                    borderWidth: 2
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        ticks: { stepSize: 1 }
                    }
                }
            }
        });
    } catch (e) {
        console.error('Failed to load analytics', e);
    }
};

function renameWorkflow(val) {
    if (!val.trim()) return;
    saveUndoState();
    window.wfState.activeWorkflow.name = val.trim();
}

window.enableWorkflowRename = function() {
    const viewContainer = document.getElementById('workflow-name-view-container');
    const editContainer = document.getElementById('workflow-name-edit-container');
    const input = document.getElementById('workflow-rename-input');
    
    if (viewContainer && editContainer && input) {
        viewContainer.classList.add('hidden');
        editContainer.classList.remove('hidden');
        input.focus();
        input.select();
    }
};

window.finishRenameWorkflow = function(input) {
    const viewContainer = document.getElementById('workflow-name-view-container');
    const editContainer = document.getElementById('workflow-name-edit-container');
    const displaySpan = document.getElementById('workflow-name-display');
    
    if (viewContainer && editContainer) {
        viewContainer.classList.remove('hidden');
        editContainer.classList.add('hidden');
    }
    
    const newVal = input.value.trim();
    if (newVal) {
        if (displaySpan) {
            displaySpan.textContent = newVal;
        }
        renameWorkflow(newVal);
    }
};

window.handleRenameKeyDown = function(e, input) {
    if (e.key === 'Enter') {
        e.preventDefault();
        input.blur();
    } else if (e.key === 'Escape') {
        if (window.wfState.activeWorkflow) {
            input.value = window.wfState.activeWorkflow.name;
        }
        input.blur();
    }
};

function filterBuilderNodes(cat) {
    window.wfState.activeCategoryFilter = cat;
    navigateTo('automation');
}

function zoomToFit() {
    window.wfState.zoom = 1.0;
    window.wfState.panX = 100;
    window.wfState.panY = 100;
    const canvas = document.getElementById('workflow-canvas');
    if (canvas) {
        canvas.style.transform = `translate(${window.wfState.panX}px, ${window.wfState.panY}px) scale(${window.wfState.zoom})`;
    }
    drawConnections();
    drawMiniMap();
}

function searchBuilderNodes(query) {
    window.wfState.searchTerm = query;
    const sidebarContainer = document.getElementById('builder-category-groups');
    if (sidebarContainer) {
        sidebarContainer.innerHTML = getGroupsHTML(query);
        lucide.createIcons();
    }
}

function refreshBuilderCanvasInline() {
    const nodesContainer = document.getElementById('canvas-nodes-container');
    if (nodesContainer) {
        nodesContainer.innerHTML = renderCanvasNodesHTML();
    }
    const sidebarContainer = document.getElementById('builder-category-groups');
    if (sidebarContainer) {
        sidebarContainer.innerHTML = getGroupsHTML(window.wfState.searchTerm || '');
    }
    const configSidebar = document.getElementById('wf-config-sidebar');
    if (configSidebar) {
        configSidebar.innerHTML = renderConfigSidebarHTML();
    }
    drawConnections();
    drawMiniMap();
    lucide.createIcons();
}

function backToWorkflowList() {
    stopBuilderAutoSave();
    window.wfState.activeWorkflow = null;
    toggleSidebarCollapsed(false);
    const assistantBtn = document.getElementById('ai-chat-trigger-btn');
    if (assistantBtn) assistantBtn.classList.remove('hidden');
    navigateTo('automation');
}

