// ----------------------------------------------------
// BOOTSTRAP INITIALIZATION
// ----------------------------------------------------
document.addEventListener('DOMContentLoaded', () => {
    // Keyboard Shortcuts (Delete node, Undo / Redo)
    document.addEventListener('keydown', (e) => {
        if (!window.wfState.activeWorkflow) return;
        
        // Exclude input fields typing
        if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT') return;
        
        if (e.key === 'Delete' || e.key === 'Backspace') {
            if (window.wfState.selectedNodeId) {
                deleteSelectedNode();
            }
        }
        
        if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
            e.preventDefault();
            undoWorkflowChange();
        }
        
        if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
            e.preventDefault();
            redoWorkflowChange();
        }
    });

    // Intercept hash change
    window.addEventListener('hashchange', () => {
        const hash = window.location.hash || '#/dashboard';
        const rawPath = hash.replace('#/', '');
        const [view, queryString] = rawPath.split('?');
        const params = {};
        if (queryString) {
            const urlParams = new URLSearchParams(queryString);
            for (const [key, value] of urlParams) {
                params[key] = value;
            }
        }
        navigateTo(view, params);
    });

    const hash = window.location.hash || '#/dashboard';
    const rawPath = hash.replace('#/', '');
    const [view, queryString] = rawPath.split('?');
    const params = {};
    if (queryString) {
        const urlParams = new URLSearchParams(queryString);
        for (const [key, value] of urlParams) {
            params[key] = value;
        }
    }
    navigateTo(view, params);

    // Automated background email & visual workflow execution cron trigger
    const triggerBackgroundCronSync = () => {
        if (typeof API_BASE_URL !== 'undefined') {
            const baseCronUrl = API_BASE_URL.replace('/api', '') + '/cron_sync.php?token=LP_CRON_SYNC_KEY_5a4c98';
            fetch(baseCronUrl).catch(() => {});
        }
    };
    triggerBackgroundCronSync();
    setInterval(triggerBackgroundCronSync, 30000); // Trigger sync every 30 seconds
});

