window.addChangesAIWorkflow = function() {
    const now = formatTime(new Date());
    
    const lastMsg = window.wfState.aiChatMessages[window.wfState.aiChatMessages.length - 1];
    if (lastMsg) {
        lastMsg.buttons = false;
        lastMsg.summary = false;
    }
    
    window.wfState.aiChatMessages.push({
        sender: 'ai',
        text: `Understood. What would you like to modify? (e.g. "Instead of Slack, send a Telegram alert" or "Assign to support rep").`,
        time: now
    });
    
    renderAIChatMessages();
    if (typeof saveCurrentChatSession === 'function') saveCurrentChatSession();
};

window.approveAIWorkflow = function() {
    const inputArea = document.getElementById('ai-input-form-container');
    if (inputArea) {
        inputArea.innerHTML = `
            <div class="flex items-center justify-center space-x-2 py-4 text-xs font-bold text-indigo-600">
                <span class="loader-spinner !w-4 !h-4 border-indigo-600 border-t-transparent"></span>
                <span>Building your workflow...</span>
            </div>
            <div class="w-full bg-slate-100 rounded-full h-1.5 overflow-hidden">
                <div id="ai-builder-progress" class="bg-indigo-600 h-1.5 transition-all duration-300" style="width: 0%"></div>
            </div>
        `;
    }
    
    window.wfState.previousActiveWorkflow = JSON.parse(JSON.stringify(window.wfState.activeWorkflow));
    
    const canvasWrap = document.getElementById('workflow-canvas');
    if (canvasWrap) {
        canvasWrap.classList.add('wf-canvas-container-blur');
    }
    
    let stepsData = window.wfState.aiSummarySteps;
    if (!stepsData || stepsData.length === 0) {
        stepsData = [
           { step: 1, type: "Trigger", label: "Email Received" },
           { step: 2, type: "Condition", label: "Check if Lead Exists?" },
           { step: 3, type: "Action (YES)", label: "Create CRM Task" },
           { step: 4, type: "Action (NO)", label: "Add to Nurture Campaign" },
           { step: 5, type: "Action", label: "Send Slack Alert" }
        ];
    }
    
    const dynamicSteps = [];
    let conditionNodeId = null;
    let yesNodeId = null;
    let noNodeId = null;
    
    stepsData.forEach((step, idx) => {
        const type = getNodeTypeFromLabel(step.label || '', step.type || '');
        const desc = getNodeDescFromLabel(type, step.label || '');
        const nodeId = 'node-' + type + '-' + step.step;
        
        let x = 320;
        let y = 80 + idx * 140;
        
        if (step.type.toLowerCase().includes('condition')) {
            conditionNodeId = nodeId;
        }
        
        if (step.type.toLowerCase().includes('(yes)') && conditionNodeId) {
            x = 120;
            y = 360;
            yesNodeId = nodeId;
        } else if (step.type.toLowerCase().includes('(no)') && conditionNodeId) {
            x = 520;
            y = 360;
            noNodeId = nodeId;
        } else if (idx > 1 && conditionNodeId) {
            x = 320;
            y = 500;
        }
        
        dynamicSteps.push({
            id: nodeId,
            type: type,
            name: step.label,
            desc: desc,
            x: x,
            y: y,
            stepType: step.type,
            config: step.config || null
        });
    });
    
    const connections = [];
    for (let i = 0; i < dynamicSteps.length; i++) {
        const curr = dynamicSteps[i];
        if (i === 0) continue;
        
        const prev = dynamicSteps[i - 1];
        
        if (curr.stepType.toLowerCase().includes('(yes)') && conditionNodeId) {
            connections.push({
                from: conditionNodeId,
                to: curr.id,
                fromId: conditionNodeId,
                toId: curr.id,
                handle: "output-yes",
                label: "Yes"
            });
        } else if (curr.stepType.toLowerCase().includes('(no)') && conditionNodeId) {
            connections.push({
                from: conditionNodeId,
                to: curr.id,
                fromId: conditionNodeId,
                toId: curr.id,
                handle: "output-no",
                label: "No"
            });
        } else if (conditionNodeId && !curr.stepType.toLowerCase().includes('condition') && i > 1) {
            if (yesNodeId) {
                connections.push({
                    from: yesNodeId,
                    to: curr.id,
                    fromId: yesNodeId,
                    toId: curr.id
                });
            }
            if (noNodeId) {
                connections.push({
                    from: noNodeId,
                    to: curr.id,
                    fromId: noNodeId,
                    toId: curr.id
                });
            }
        } else {
            connections.push({
                from: prev.id,
                to: curr.id,
                fromId: prev.id,
                toId: curr.id
            });
        }
    }
    
    const body = document.body;
    let stepsHTML = '';
    dynamicSteps.forEach((node, idx) => {
        stepsHTML += `<div id="ai-step-${idx}" class="flex items-center space-x-1 ${idx > 0 ? 'hidden' : ''}"><span>• Creating ${node.name}...</span></div>`;
    });
    stepsHTML += `<div id="ai-step-final" class="flex items-center space-x-1 hidden"><span>• Finalizing...</span></div>`;
    
    const progressOverlay = document.createElement('div');
    progressOverlay.id = 'ai-progress-overlay';
    progressOverlay.className = "fixed top-20 left-1/2 transform -translate-x-1/2 bg-white/95 border border-slate-200 px-6 py-4 rounded-2xl shadow-xl z-50 flex flex-col space-y-2 w-80 animate-fade-in";
    progressOverlay.innerHTML = `
        <div class="flex items-center space-x-2 text-xs font-bold text-indigo-700 justify-center">
            <span class="loader-spinner !w-3.5 !h-3.5 border-indigo-600 border-t-transparent"></span>
            <span>AI Building Workflow Live</span>
        </div>
        <div id="ai-progress-steps" class="space-y-1 text-[10px] text-slate-500 font-semibold pl-2">
            ${stepsHTML}
        </div>
    `;
    body.appendChild(progressOverlay);
    
    window.wfState.activeWorkflow.nodes = [];
    window.wfState.activeWorkflow.connections = [];
    refreshBuilderCanvasInline();
    
    const stepsAnimation = [];
    
    dynamicSteps.forEach((node, idx) => {
        stepsAnimation.push({
            name: node.name,
            action: () => {
                let config = node.config || {};
                if (!config || Object.keys(config).length === 0) {
                    if (node.type === 'whatsapp_outbound') {
                        config = {
                            to: '{{contact.phone}}',
                            message: 'Hi {{contact.name}}, thanks for reaching out! We received your message and will get back to you shortly.'
                        };
                    } else if (node.type === 'send_email') {
                        config = {
                            toEmail: '{{contact.email}}',
                            subject: 'Inquiry Received',
                            body: 'Hi {{contact.name}},\n\nThank you for reaching out to us. We have received your message and our team will get back to you shortly.\n\nBest regards,\nLinkPilot Team'
                        };
                    } else if (node.type === 'email_received') {
                        config = {
                            folder: 'Inbox',
                            unreadOnly: true
                        };
                    } else if (node.type === 'whatsapp_received') {
                        config = {
                            phone: 'All'
                        };
                    }
                }

                window.wfState.activeWorkflow.nodes.push({
                    id: node.id,
                    type: node.type,
                    name: node.name,
                    desc: node.desc,
                    x: node.x,
                    y: node.y,
                    config: config,
                    execStatus: "success",
                    execTime: Math.floor(Math.random() * 40 + 50) + "ms"
                });
                
                connections.forEach(conn => {
                    if (conn.toId === node.id) {
                        const exists = window.wfState.activeWorkflow.connections.some(c => c.fromId === conn.fromId && c.toId === conn.toId);
                        if (!exists) {
                            window.wfState.activeWorkflow.connections.push(conn);
                        }
                    }
                });
                
                const stepEl = document.getElementById('ai-step-' + idx);
                if (stepEl) {
                    stepEl.innerHTML = `<span class="text-emerald-500 font-bold">✔ Created ${node.name}</span>`;
                }
                const nextStepEl = document.getElementById('ai-step-' + (idx + 1));
                if (nextStepEl) {
                    nextStepEl.classList.remove('hidden');
                }
                
                appendAINarration(`✔ Created ${node.name} (${node.desc})`);
            }
        });
    });
    
    stepsAnimation.push({
        name: "Finalize Layout",
        action: () => {
            const finalEl = document.getElementById('ai-step-final');
            if (finalEl) {
                finalEl.innerHTML = `<span class="text-emerald-500 font-bold">✔ Alignment connection nodes arranged</span>`;
            }
            appendAINarration("✔ Arranged workflow nodes visual graph layout successfully");
        }
    });
    
    let currentStep = 0;
    
    function runNextStep() {
        if (currentStep < stepsAnimation.length) {
            stepsAnimation[currentStep].action();
            const pct = Math.round(((currentStep + 1) / stepsAnimation.length) * 100);
            const prg = document.getElementById('ai-builder-progress');
            if (prg) prg.style.width = pct + '%';
            
            refreshBuilderCanvasInline();
            zoomToFit();
            
            currentStep++;
            setTimeout(runNextStep, 1300);
        } else {
            finalizeWorkflowCreation();
        }
    }
    
    setTimeout(runNextStep, 1000);
};

function appendAINarration(narrationText) {
    const container = document.getElementById('ai-chat-messages-container');
    if (!container) return;
    
    const now = formatTime(new Date());
    const wrap = document.createElement('div');
    wrap.className = "flex items-start justify-start space-x-2.5 w-full";
    wrap.innerHTML = `
        <div class="h-7 w-7 rounded-full bg-emerald-50 border border-emerald-250 flex items-center justify-center shrink-0 shadow-xs">
            <i data-lucide="check-circle" class="h-3.5 w-3.5 text-emerald-600"></i>
        </div>
        <div class="flex flex-col items-start w-full">
            <div class="chat-message ai bg-emerald-50/50 border border-emerald-150 text-emerald-800 font-semibold py-1.5 px-3 text-[10px]">${narrationText}</div>
            <span class="text-[8px] text-slate-400 ml-1 mb-2">${now}</span>
        </div>
    `;
    container.appendChild(wrap);
    lucide.createIcons();
    container.scrollTop = container.scrollHeight;
}

function finalizeWorkflowCreation() {
    const canvasWrap = document.getElementById('workflow-canvas');
    if (canvasWrap) {
        canvasWrap.classList.remove('wf-canvas-container-blur');
    }
    
    const overlay = document.getElementById('ai-progress-overlay');
    if (overlay) overlay.remove();
    
    showConfettiCelebration();
    
    const inputArea = document.getElementById('ai-input-form-container');
    if (inputArea) {
        inputArea.innerHTML = `
            <div class="p-3 bg-emerald-50 border border-emerald-150 rounded-xl space-y-2 text-center text-xs">
                <div class="font-bold text-emerald-800">✨ Workflow Built Successfully!</div>
                <div class="text-[10px] text-emerald-600">Constructed all dynamic nodes andconnection routing links.</div>
                <div class="flex items-center space-x-2 pt-1 shrink-0">
                    <button onclick="toggleAIBuilderDrawer(false)" class="flex-grow py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-bold transition">Open Builder</button>
                    <button onclick="runWorkflowSimulation(this)" class="py-1.5 px-3 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-bold transition">Run Test</button>
                    <button onclick="undoAIGeneration()" class="py-1.5 px-3 bg-slate-700 hover:bg-slate-650 text-white rounded-lg font-bold transition">Undo</button>
                </div>
            </div>
        `;
    }
    
    saveWorkflowToHistory();
    showNotification('success', 'Workflow created successfully by AI!');
}

function saveWorkflowToHistory() {
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    
    window.wfState.aiHistory.push({
        id: "ai-sess-" + now.getTime(),
        title: window.wfState.activeWorkflow.name || "AI Generated Campaign Flow",
        date: dateStr,
        nodes: JSON.parse(JSON.stringify(window.wfState.activeWorkflow.nodes)),
        connections: JSON.parse(JSON.stringify(window.wfState.activeWorkflow.connections))
    });
    localStorage.setItem('linkpilot_ai_history', JSON.stringify(window.wfState.aiHistory));
}

window.undoAIGeneration = function() {
    if (window.wfState.previousActiveWorkflow) {
        window.wfState.activeWorkflow = window.wfState.previousActiveWorkflow;
        refreshBuilderCanvasInline();
        showNotification('info', 'AI workflow generation rolled back.');
        toggleAIBuilderDrawer(false);
    }
};

window.saveCurrentChatSession = function() {
    if (window.wfState.aiChatMessages.length === 0) return;
    
    if (!window.wfState.currentChatSessionId) {
        window.wfState.currentChatSessionId = 'chat-sess-' + Date.now();
    }
    
    let sessions = [];
    try {
        sessions = JSON.parse(localStorage.getItem('linkpilot_ai_chat_sessions')) || [];
    } catch (e) {
        sessions = [];
    }
    
    const firstUserMsg = window.wfState.aiChatMessages.find(m => m.sender === 'user');
    let title = firstUserMsg ? firstUserMsg.text : (window.wfState.aiChatMessages[0]?.text || "Chat Session");
    if (title.length > 36) {
        title = title.substring(0, 35) + "...";
    }
    
    const sessIndex = sessions.findIndex(s => s.id === window.wfState.currentChatSessionId);
    const dateStr = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    
    const sessionData = {
        id: window.wfState.currentChatSessionId,
        title: title,
        date: dateStr,
        messages: JSON.parse(JSON.stringify(window.wfState.aiChatMessages))
    };
    
    if (sessIndex >= 0) {
        sessions[sessIndex] = sessionData;
    } else {
        sessions.unshift(sessionData);
    }
    
    localStorage.setItem('linkpilot_ai_chat_sessions', JSON.stringify(sessions));
};

function renderAIHistoryPanel() {
    const panel = document.getElementById('ai-history-tab-panel');
    if (!panel) return;
    
    let sessions = [];
    try {
        sessions = JSON.parse(localStorage.getItem('linkpilot_ai_chat_sessions')) || [];
    } catch (e) {
        sessions = [];
    }
    
    if (sessions.length === 0) {
        panel.innerHTML = `
            <div class="flex-grow flex flex-col items-center justify-center p-6 text-center text-slate-400 space-y-2 select-none my-auto h-full">
                <i data-lucide="history" class="h-8 w-8 text-slate-300"></i>
                <div class="text-xs font-bold uppercase tracking-wider text-slate-500">No Chat History</div>
                <div class="text-[10px] leading-relaxed max-w-[200px]">Your conversational AI chat logs will appear here. Click to resume any past chat.</div>
            </div>
        `;
        lucide.createIcons();
        return;
    }
    
    let html = `
        <div class="flex items-center justify-between pl-1 mb-2">
            <span class="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Past Conversations</span>
            <button onclick="startNewChatSession()" class="text-[9px] font-extrabold text-indigo-650 hover:text-indigo-800 transition flex items-center space-x-0.5">
                <i data-lucide="plus" class="h-3 w-3"></i>
                <span>New Chat</span>
            </button>
        </div>
        <div class="space-y-2.5">
    `;
    
    sessions.forEach(sess => {
        const isCurrent = sess.id === window.wfState.currentChatSessionId;
        html += `
            <div onclick="openPreviousChatSession('${sess.id}')" class="p-3 bg-white hover:bg-slate-50 border ${isCurrent ? 'border-indigo-400 ring-1 ring-indigo-400/20' : 'border-slate-200'} rounded-xl space-y-1.5 text-left shadow-xs cursor-pointer transition group">
                <div class="flex items-center justify-between shrink-0">
                    <div class="font-extrabold text-slate-800 text-xs truncate max-w-[70%] group-hover:text-indigo-650 transition">${sess.title}</div>
                    <span class="text-[8px] font-bold text-slate-400">${sess.date}</span>
                </div>
                <div class="flex items-center justify-between shrink-0">
                    <div class="text-[9px] text-slate-500">
                        <span class="font-semibold text-slate-650">${sess.messages.length} Messages</span>
                    </div>
                    <button onclick="deleteChatSession('${sess.id}'); event.stopPropagation();" class="p-1 hover:bg-red-50 text-slate-400 hover:text-red-650 rounded transition" title="Delete conversation">
                        <i data-lucide="trash-2" class="h-3.5 w-3.5"></i>
                    </button>
                </div>
            </div>
        `;
    });
    
    html += `</div>`;
    panel.innerHTML = html;
    lucide.createIcons();
}

window.openPreviousChatSession = function(sessId) {
    let sessions = [];
    try {
        sessions = JSON.parse(localStorage.getItem('linkpilot_ai_chat_sessions')) || [];
    } catch (e) {
        sessions = [];
    }
    
    const found = sessions.find(s => s.id === sessId);
    if (found) {
        window.wfState.currentChatSessionId = found.id;
        window.wfState.aiChatMessages = JSON.parse(JSON.stringify(found.messages));
        
        switchAIBuilderTab('chat');
        showNotification('success', 'Conversation loaded.');
    }
};

window.startNewChatSession = function() {
    window.wfState.currentChatSessionId = null;
    window.wfState.aiChatMessages = [];
    window.wfState.aiStep = 0;
    
    switchAIBuilderTab('chat');
    showNotification('success', 'New conversation started.');
};

window.deleteChatSession = function(sessId) {
    let sessions = [];
    try {
        sessions = JSON.parse(localStorage.getItem('linkpilot_ai_chat_sessions')) || [];
    } catch (e) {
        sessions = [];
    }
    
    sessions = sessions.filter(s => s.id !== sessId);
    localStorage.setItem('linkpilot_ai_chat_sessions', JSON.stringify(sessions));
    
    if (window.wfState.currentChatSessionId === sessId) {
        window.wfState.currentChatSessionId = null;
        window.wfState.aiChatMessages = [];
        window.wfState.aiStep = 0;
    }
    
    renderAIHistoryPanel();
    showNotification('info', 'Chat conversation deleted.');
};

function showConfettiCelebration() {
    const container = document.body;
    const colors = ['#6366f1', '#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6'];
    
    for (let i = 0; i < 40; i++) {
        const p = document.createElement('div');
        p.className = 'confetti-piece';
        p.style.left = Math.random() * 100 + 'vw';
        p.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
        p.style.animationDelay = Math.random() * 1.5 + 's';
        p.style.transform = `rotate(${Math.random() * 360}deg)`;
        
        // Random dimensions
        const size = Math.random() * 6 + 6;
        p.style.width = size + 'px';
        p.style.height = size + 'px';
        p.style.borderRadius = Math.random() > 0.5 ? '50%' : '0%';
        
        container.appendChild(p);
        
        // Cleanup after animation completes
        setTimeout(() => {
            p.remove();
        }, 4000);
    }
}
